#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). MIT License.
# Removes Proton Updater. Installed Proton versions and Steam settings are NOT touched.
set -euo pipefail
systemctl --user disable --now proton-updater.timer 2>/dev/null || true
rm -f ~/.config/systemd/user/proton-updater.{service,timer} ~/.local/bin/proton-updater ~/.local/bin/proton-updater-gui \
      ~/.local/share/applications/proton-updater.desktop
rm -rf ~/.local/share/proton-updater ~/.cache/proton-updater
systemctl --user daemon-reload
echo "Removed. (Settings kept in ~/.config/proton-updater — delete that folder too if you want.)"
echo "Видалено. (Налаштування лишились у ~/.config/proton-updater — прибери й цю теку, якщо хочеш.)"
